import json


def append_delivery_guide(doc, root, add_table, add_code_block):
    report = json.loads((root / 'reports' / 'delivery_validation.json').read_text(encoding='utf-8'))
    doc.add_page_break()
    doc.add_heading('Реализация плана до десятого этапа', level=1)
    doc.add_paragraph('Обновление от 17 ноября 2026. Эта глава описывает новый проверенный программный контур и уточняет статус прежних записей журнала. Мы получили работающий локальный API, демонстрационный поиск с оценкой, цитируемые ответы и контейнер. Корпус data/demo содержит инструкции по самому проекту, составленные автоматически. Это не банковские инструкции и не экспертно размеченная база. Поэтому показатели демонстрации подтверждают работу программного контура, но не пригодность для банковских клиентов.')
    add_table(doc, ['Этап плана', 'Фактический результат', 'Открытое условие'], [
        ('1 Проверка кода', f"{report['checks']['tests_run']} успешных тестов и отдельный Uvicorn HTTP запуск", 'Тестовые сценарии не покрывают все реальные ошибки'),
        ('2 База знаний', '16 демонстрационных статей на двух языках с provenance', 'Нужны разрешённые реальные статьи и подтверждение владельца'),
        ('3 Разметка', '24 calibration и 24 holdout запроса; аудит совпадений', 'Авторство вопросов и корпуса общее; экспертная независимость не установлена'),
        ('4 Эксперименты', 'TF-IDF и 6 BM25 конфигураций; пороги по языкам', 'Выбор относится только к демонстрационному корпусу'),
        ('5 Оценка', 'Выбранный на calibration кандидат проверен на demo holdout', 'Для реальной приёмки нужен независимый экспертный benchmark'),
        ('6 Сквозной API', 'Поиск, классификация, ответ, отказ и метрики проверены по HTTP', 'Корпус поддержки пользователей пока не подключён'),
        ('7 Улучшения', 'Проведено сравнение BM25 параметров; baseline сохранён для сравнения', 'Transformers и embeddings требуют отдельного обоснованного эксперимента'),
        ('8 Ответы', 'Extractive, контрактные тесты и реальный smoke локальной Qwen2.5', 'Независимая экспертная оценка answer correctness не выполнена'),
        ('9 Упаковка', 'Dockerfile, Compose, lock зависимостей, localhost, auth и лимит', 'Распределённый rate limit, TLS и внешняя эксплуатационная приёмка'),
        ('10 Демонстрация', 'Общий ноутбук 06 и подробная глава с вопросами для интервью', 'Не заявлять на собеседовании невыполненные эксперименты')])

    lessons = [
        ('1 Проверяем программное поведение',
         'Сначала мы проверили существующие примитивы отдельно от реальных данных. Это позволяет обнаружить ошибки ранжирования и API до дорогой предметной оценки. В тестах есть статьи на английском и русском, положительные запросы и запросы без ответа. Для каждого ранжировщика проверяются top-1, фильтрация языка, Recall@1, MRR и отказ при нулевом score. Дополнительно проверяются дубли ID, draft-статус, ошибочная дата, параметры chunking и NaN/Infinity в BM25.',
         'Подходы: ручной запуск удобен для первого знакомства; unit-тест фиксирует частный контракт; интеграционный тест проверяет связку загрузчика, индекса и метрик; реальный HTTP запуск проверяет ещё и серверный процесс. Мы используем все эти уровни. TestClient подменяет загрузку intent-модели в части тестов, поэтому отдельный Uvicorn smoke проверяет настоящий сохранённый артефакт.',
         'Файлы tests/test_retrieval_integration.py и tests/test_api_workflow.py дополняют прежние тесты аудита. scripts/check_project.py запускает suite, проверяет синтаксис ячеек ноутбуков и сохраняет JSON с хешами исходников. Успех теста означает ожидаемое поведение на заданном сценарии, а не точность на клиентских обращениях.'),
        ('2 Создаём прозрачный демонстрационный корпус',
         'Реальных разрешённых банковских статей пользователь ещё не предоставил. Чтобы получить рабочий программный контур, мы написали инструкции о проекте: установка, запуск, readiness, классификация, схема статей, разделение выборок, тесты и приватность артефактов. Для восьми тем подготовлены английская и русская версии. JSONL можно открыть в PyCharm как обычный текст.',
         'Альтернативы: скопировать чужой FAQ без проверки лицензии, придумать банковские инструкции либо использовать контролируемые инструкции о собственном приложении. Выбран последний вариант. В provenance явно записаны автоматическое авторство, отсутствие экспертного review и роль demonstration_only. Поле approved нужно для совместимости загрузчика демо и не означает бизнес-одобрение.',
         'В продуктивном процессе владелец статьи отвечает за содержание и актуальность. Наличие полей owner/license/status само по себе не доказывает достоверность. Для перехода к реальным данным нужен предметный владелец, допустимый источник, дата пересмотра и экспертная проверка содержания.'),
        ('3 Разделяем подготовку и финальную оценку',
         'Для calibration составлены 16 answerable и 8 unanswerable запросов. В demo holdout такое же число запросов. require_independent_query_splits проверяет Unicode-нормализацию, повторы и общие query_group_id. Однако разные идентификаторы групп не доказывают семантическую независимость: её нужно обеспечивать при разметке по происхождению исходных обращений.',
         'Можно разделить строки случайно, по пользователю, по диалогу, по исходному кейсу или по времени. Для перефразированных запросов разумно разделять целые исходные кейсы. В продакшене временной holdout помогает оценивать будущие обращения, но требует отдельно учитывать изменение базы статей.',
         'Наша демонстрационная разметка создана тем же автором, что и статьи. Она легко разделима по словарю и мала. Поэтому даже отсутствие exact overlap не делает её независимой экспертной оценкой. На интервью нужно прямо сказать, что реальная предметная приёмка остаётся открытой.'),
        ('4 Выбираем метод только на calibration',
         'Сравниваются word TF-IDF и BM25 при k1 из 1.0, 1.5, 2.0 и b из 0.3, 0.75. TF-IDF — прозрачное векторное сравнение; BM25 использует насыщение частоты термина и поправку на длину. Для каждого кандидата считаются Recall@5/MRR и пороговые кривые отдельно для языков.',
         'Правило выбора заранее задано кодом: средний по языкам supported-answer F1, затем MRR и Recall@5; при полном равенстве предпочтение простому TF-IDF. Порог для каждого языка берётся на calibration. Сначала сравниваются кандидаты, затем сохраняется selected_config.json, и только потом начинается holdout.',
         'scripts/run_retrieval_experiment.py сохраняет хеши трёх входных файлов и исходников. Повторный запуск с теми же входами читает готовый результат. Маркер holdout_evaluation_started.json останавливает автоматический повтор после незавершённой оценки. Это дисциплина выполнения эксперимента, но не техническая защита от намеренного подглядывания в файл.'),
        ('5 Интерпретируем финальные числа',
         'Recall@5 показывает, найдены ли размеченные статьи в первых пяти уникальных документах. MRR учитывает позицию первой релевантной статьи. Метрики ранжирования считаются только для answerable запросов. Для unanswerable оценивается ложное принятие, а coverage показывает долю запросов, прошедших порог.',
         'Высокий Recall@5 совместим с ошибочным top-1: правильная статья может быть второй или третьей. Даже высокий MRR не гарантирует хороший отказ. Поэтому рядом рассматриваются supported-answer precision/recall/F1 и unsafe_accept_rate. В русской демонстрационной группе есть неверно принятый top-1, несмотря на полный Recall@5.',
         'После просмотра holdout мы не меняли параметры по его ошибкам. На этих данных допустима проверка программных исправлений, но нельзя выдавать повторные запуски за новые независимые эксперименты. Для следующего честного сравнения моделей нужен новый предметный holdout.'),
        ('6 Проверяем полный пользовательский запрос',
         'scripts/verify_demo_http.py запускает отдельный Uvicorn на свободном loopback-порту, ждёт knowledge readiness и вызывает настоящие endpoints. Проверяются intent сохранённой модели, поиск, цитата, отказ без доказательств, HTTP 401/422 и операционные метрики. В finally процесс завершается даже при ошибке.',
         'TestClient полезен для быстрых сценариев, но не проверяет запуск отдельного процесса и сетевой транспорт. Поэтому реальный HTTP smoke является отдельным слоем проверки. Таймер round trip включает клиент, сеть loopback, серверную обработку и получение ответа; он не равен времени только матричного поиска.',
         'Мы не повторяем BANKING77 official test. Для демонстрации классификатора используется один контрольный текст I lost my card. Это smoke test загрузки артефакта, а не новая оценка Accuracy. Итоговые test-метрики классификатора остаются прежними.'),
        ('7 Решаем нужны ли сложные модели',
         'Для демонстрации выбран BM25 по calibration; точные результаты приводятся ниже из артефакта. Это локальное улучшение относительно word TF-IDF на данном наборе. Общий вывод о превосходстве BM25 на всех обращениях из него не следует.',
         'Embeddings полезны при несовпадении лексики; hybrid retrieval сочетает lexical и dense candidates; reranker уточняет порядок небольшого списка. Каждый вариант добавляет зависимости, latency, стоимость обновления и необходимость калибровать новые score. На 16 автоматически написанных статьях такой benchmark недостаточен для обоснованного выбора.',
         'Transformers, LoRA и QLoRA не были обучены в этом проходе. Обещание использовать современную технологию не заменяет проверяемую гипотезу. Следующий предметный эксперимент должен объяснять конкретные ошибки baseline, бюджет ресурсов и ожидаемый выигрыш на независимом наборе.'),
        ('8 Формируем ответ с проверяемыми источниками',
         'Новый POST /v1/knowledge/answer сначала использует тот же поиск и порог. Если статус не threshold_passed, возвращается abstained. Extractive режим выдаёт точный текст верхнего фрагмента и его источник. Это работающий baseline ответа, который не перефразирует источник.',
         'Ollama-режим запрашивает JSON-массив цитат из максимум трёх фрагментов. Сервер сверяет chunk_id со списком переданных доказательств, а quote — с точной подстрокой исходного фрагмента. Ответ строится самим сервером из проверенных цитат. Выдуманный ID, изменённая цитата или недоступный провайдер приводят к контролируемому 503; пустой список даёт отказ.',
         'Здесь LLM выполняет выбор цитат, а не свободное сочинение ответа. Подлинность цитаты не доказывает её релевантность: неправильный top-1 всё ещё может дать неправильную выдержку. Полноценная оценка включает answer correctness, groundedness, relevance и корректный отказ. Дополнительно выполнены четыре реальных запроса к локальной Qwen2.5 0.5B на CPU; результаты приведены ниже. Это проверка интеграции на выбранных calibration-примерах, а не независимая предметная оценка.'),
        ('9 Упаковываем и ограничиваем локальную эксплуатацию',
         'Dockerfile использует Python 3.14 slim с зафиксированным digest и requirements-container.lock из реально собранного Linux-окружения. Приложение запускается от appuser. Compose публикует порт только на 127.0.0.1, монтирует модель read-only, запрещает дополнительные capabilities и повышение привилегий. Для временного каталога демонстрационных результатов используется tmpfs.',
         'SUPPORT_API_KEY защищает /v1 и /metrics через x-api-key. Простой общий лимит запросов и счётчики работают в одном процессе. Это подходит для локального запуска; несколько workers потребуют общего хранилища лимитов и метрик. Внешнее размещение требует TLS на reverse proxy, управления секретами, централизованного мониторинга, резервирования и согласованной политики доступа.',
         'Readiness базы знаний отделена от готовности intent-модели. Контейнер без модели может искать по статьям, но классификация вернёт 503. Healthcheck Compose проверяет готовность knowledge-индекса. Каталог моделей не включён в образ: доверенный joblib монтируется с машины владельца. Загружать joblib из неизвестного источника нельзя, потому что десериализация способна выполнять код.'),
        ('10 Воспроизводим и объясняем проект',
         'notebooks/06_complete_demo.ipynb объединяет просмотр provenance, статей, аудита, таблиц кандидатов и конечных результатов. Отдельная ячейка запускает HTTP smoke. Весь пример доступен без скачивания статей: data/demo отслеживается Git и не содержит клиентских данных. Реальные data/knowledge и work остаются локальными.',
         'На интервью последовательность рассказа должна быть такой: задача и ограничения данных; baseline; предотвращение утечки; эксперимент и метрика выбора; независимая оценка; контракт API; режим отказа; эксплуатационные ограничения. Нужно отличать измеренную точность BANKING77 от демонстрационных retrieval-чисел.',
         'README по просьбе пользователя больше не редактируется. Текущие инструкции находятся в этой главе, общем ноутбуке и машиночитаемом reports/delivery_validation.json. Для каждого этапа указано, что реально проверено, а что требует предметных данных или внешнего сервиса.')]
    for title, purpose, alternatives, implementation in lessons:
        doc.add_heading(title, level=2)
        for paragraph in [purpose, alternatives, implementation]:
            doc.add_paragraph(paragraph)

    doc.add_heading('Измеренные результаты демонстрационного корпуса', level=2)
    retrieval = report['retrieval']
    add_table(doc, ['Метод', 'k1 и b', 'Calibration Recall@5', 'Calibration MRR', 'Calibration F1'], [
        (row['method'], str(row['parameters']), f"{row['recall_at_5']:.4f}", f"{row['mrr']:.4f}", f"{row['calibration_f1']:.4f}")
        for row in retrieval['candidate_metrics']])
    doc.add_paragraph(f"Выбран {retrieval['selected_method']} с параметрами {retrieval['selected_parameters']}. Demo holdout Recall@5={retrieval['holdout_recall_at_5']:.4f}, MRR={retrieval['holdout_mrr']:.4f}. Эти значения получены на автоматически составленном наборе и не являются оценкой банковской системы.")
    add_table(doc, ['Язык', 'Порог', 'Coverage', 'Precision', 'Recall', 'F1', 'Ошибочные принятия'], [
        (row['language'], f"{row['threshold']:.4f}", f"{row['coverage']:.4f}", f"{row['supported_answer_precision']:.4f}",
         f"{row['supported_answer_recall']:.4f}", f"{row['supported_answer_f1']:.4f}", f"{row['unsafe_accept_rate']:.4f}")
        for row in retrieval['holdout_threshold_metrics']])
    doc.add_paragraph('Разбор русской группы: из восьми answerable вопросов система правильно поддержала шесть; всего приняла семь запросов. Поэтому precision=6/7≈0.8571, recall=6/8=0.75 и F1=0.8. Один принятый top-1 нерелевантен, хотя правильная статья присутствует в top-5. Это конкретный пример того, почему нельзя оценивать безопасность ответа только по Recall@5.')
    http = report['http']
    doc.add_paragraph(f"Отдельный локальный Uvicorn: {http['request_count']} поисковых HTTP запросов, P50={http['p50_ms']:.2f} мс, P95={http['p95_ms']:.2f} мс. Запросы последовательные, выборка маленькая, результаты зависят от прогрева и машины. Это не нагрузочное SLO.")
    docker = report.get('docker', {})
    doc.add_paragraph(f"Проверка Docker: статус {docker.get('health')}, пользователь {docker.get('user')}, read-only rootfs={docker.get('read_only_rootfs')}. В контейнере получены цитируемый ответ и intent {docker.get('classification_intent')}. Digest образа сохранён в reports/delivery_validation.json.")
    notebook = report.get('notebook', {})
    doc.add_paragraph(f"Общий ноутбук выполнен в Jupyter: {notebook.get('executed')}; ячеек с ошибками: {notebook.get('errors')}; исполняемый код совпадает с опубликованным: {notebook.get('source_code_matches')}.")
    llm = report.get('llm')
    if llm:
        doc.add_heading('Реальная локальная языковая модель', level=2)
        doc.add_paragraph(f"Провайдер Ollama вызван без подмены HTTP. Модель {llm['model']}, размер файла {llm['model_size_bytes'] / 1024**2:.1f} MiB; digest {llm['model_digest']}. Проверено {llm['case_count']} выбранных calibration-кейса, нужный источник процитирован в {llm['supported_expected_count']}. Ожидаемые источники заранее заданы разработчиком и не прошли независимую экспертную разметку.")
        add_table(doc, ['Язык', 'Ожидаемый источник', 'Результат', 'Источник верен', 'Секунды'], [
            (row['language'], row['expected_document_id'], row['status'], str(row.get('expected_document_cited', False)), f"{row['latency_seconds']:.2f}")
            for row in llm['cases']])
        doc.add_paragraph('Модель выбрана для дешёвой CPU-проверки structured output и мультиязычных цитат. Она не выбиралась как лучшая по предметному качеству. Холодный первый запрос включает загрузку модели; последующие запросы выполняются с прогретым процессом. Ограничение контейнера: 2 CPU и 2 GiB RAM.')

    doc.add_heading('Команды для самостоятельного запуска', level=2)
    add_code_block(doc, '''python -m pip install -r requirements.txt
python -m pip install httpx
python -m pip install -r requirements-validation.txt
python scripts/check_project.py
python scripts/run_retrieval_experiment.py
python scripts/verify_demo_http.py
python scripts/start_demo.py''')
    doc.add_paragraph('Для Docker сначала запустите Docker Desktop и задайте собственный секрет в PowerShell. Следующий пример использует значение-заглушку, которое нужно заменить. Контейнер слушает только localhost; TLS в этом примере не настраивается.')
    add_code_block(doc, '''$env:SUPPORT_API_KEY = 'replace-with-your-random-secret'
docker compose up --build -d --wait
docker compose ps
docker compose logs --tail 50
docker compose down''')
    doc.add_paragraph('Для совместного запуска API и локальной LLM используется дополнительный Compose-файл. При первом запуске необходимо скачать модель. Сервис LLM не публикует порт наружу; API обращается к нему по внутренней сети Compose. После загрузки задайте mode=ollama в JSON запроса.')
    add_code_block(doc, '''docker compose -f compose.yaml -f compose.llm.yaml up --build -d --wait
docker compose -f compose.yaml -f compose.llm.yaml exec ollama ollama pull qwen2.5:0.5b
docker compose -f compose.yaml -f compose.llm.yaml down''')
    doc.add_paragraph('Схема API: http://127.0.0.1:8000/docs. Для защищённых маршрутов передайте заголовок x-api-key. Пример JSON для ответа приведён ниже. При неизвестном языке, неподходящем пороге или изменении корпуса ожидается отказ, а не выдуманный ответ.')
    add_code_block(doc, '''{
  "text": "Как запустить локальный API?",
  "language": "ru",
  "mode": "extractive"
}''')

    doc.add_heading('Вопросы для собеседования с развёрнутыми ответами', level=1)
    questions = [
        ('Какую задачу решает проект?', 'Первая задача — классифицировать английское обращение в один из 77 intents BANKING77. Вторая — найти подтверждающий документ и выдать выдержку с источником либо отказаться. Эти задачи имеют разные наборы данных и критерии качества; метка intent сама по себе не содержит ответа клиенту.'),
        ('Почему начали с классических моделей?', 'TF-IDF и линейные модели быстро обучаются, дают сильный baseline для коротких текстов и позволяют проверить данные и метрики без GPU. Сложная модель имеет смысл после анализа конкретных ошибок и измеримого сравнения по качеству, latency и ресурсам.'),
        ('Как работает TF-IDF?', 'TF задаёт вес часто встречающегося признака в документе, IDF уменьшает вес признаков, распространённых почти во всех документах. После нормализации векторов скалярное произведение соответствует cosine similarity. Векторизатор должен обучаться на train, а не на validation/test.'),
        ('Зачем объединять word и char признаки?', 'Слова хорошо описывают тематику, а char_wb n-граммы помогают с морфологией, опечатками и частями незнакомых слов. Объединение увеличивает размер пространства, поэтому его пользу нужно проверять по validation и эксплуатационным характеристикам.'),
        ('Как работает Linear SVM?', 'Линейный классификатор ищет разделяющие гиперплоскости с большим зазором и штрафом за ошибки. C регулирует компромисс между регуляризацией и ошибками обучения. Decision score задаёт расстояние относительно разделяющей поверхности, но не вероятность правильного ответа.'),
        ('Почему не возвращается confidence?', 'LinearSVC не выдаёт калиброванную вероятность. Называть произвольный decision score confidence было бы вводящим в заблуждение. Для вероятностей нужен отдельный calibration-протокол, например sigmoid или isotonic на выделенных данных, с проверкой калибровочных метрик.'),
        ('Чем Macro F1 отличается от Weighted F1?', 'Macro F1 усредняет F1 классов с равными весами, поэтому редкий класс влияет так же, как частый. Weighted F1 взвешивает по support и может скрыть низкое качество редких intents. У BANKING77 test одинаковое число примеров на класс, поэтому эти средние близки по конструкции набора.'),
        ('Почему Accuracy недостаточно?', 'Accuracy считает долю верных меток, но при дисбалансе может быть высокой даже у модели, игнорирующей редкий класс. Поэтому мы смотрим Macro F1, per-class precision/recall, confusion matrix и реальные примеры ошибок.'),
        ('Зачем confusion matrix?', 'Матрица показывает, какие классы модель путает между собой. Она помогает отличить локальную проблему похожих intents от общего ухудшения. По матрице нельзя автоматически менять labels: сначала нужно прочитать тексты и проверить корректность разметки.'),
        ('Как предотвращается data leakage?', 'Векторизатор и модель находятся внутри train Pipeline; гиперпараметры выбираются на validation. Дубли и общие группы обращений не должны пересекать независимые части. Official test не используется для подбора, а хранится для финальной оценки зафиксированного кандидата.'),
        ('Почему нельзя повторно подбирать по test?', 'После выбора параметров по test его примеры влияют на решение разработчика, и результат перестаёт быть независимой оценкой. Даже ручное сравнение десятков кандидатов по test создаёт оптимистическое смещение. Для новой финальной проверки нужен новый набор.'),
        ('Что показывает Recall@5?', 'Для каждого answerable запроса это доля размеченных релевантных документов, попавших в первые пять уникальных статей. Затем значения усредняются. Если релевантных статей несколько, одного попадания недостаточно для Recall=1.'),
        ('Что показывает MRR?', 'Берётся обратный ранг первого релевантного документа и усредняется по answerable запросам. Релевантный документ первым даёт 1, вторым — 1/2, третьим — 1/3. MRR не оценивает полноту всех релевантных документов и не измеряет отказ на вопросах без ответа.'),
        ('Почему оценка ведётся по уникальным статьям?', 'Несколько соседних чанков одной статьи не должны занимать все позиции document-level top-k и искусственно повышать видимость одного источника. Мы дедуплицируем document_id, сохраняя порядок лучшего фрагмента.'),
        ('Как работает BM25?', 'BM25 суммирует вклады совпавших терминов с учётом их редкости, насыщения term frequency и длины документа. k1 задаёт насыщение частоты, b — силу нормализации длины. Его score имеет другую шкалу, чем TF-IDF cosine.'),
        ('Почему пороги задаются по языкам?', 'Разная морфология, словарь, длина и состав корпуса меняют распределение score. Один численный порог не обязан одинаково работать для русского и английского. При этом язык должен определяться корректно и совпадать с языком размеченных релевантных статей.'),
        ('Как выбирался порог?', 'На calibration перебирались значения score и вычислялись coverage, supported-answer precision/recall/F1 и ложные принятия. Решение фиксируется до holdout. Высокий порог уменьшает число ответов, но может увеличить отказы на answerable запросах.'),
        ('Что такое coverage?', 'Это доля всех запросов, для которых система приняла кандидата по порогу. Coverage сама по себе не качество: система может отвечать на всё и ошибаться. Поэтому её рассматривают вместе с precision и риском неверного принятия.'),
        ('Почему Recall@5=1 не означает безопасный ответ?', 'Релевантная статья может находиться в top-5, а top-1 быть нерелевантным. Если ответ строится по top-1 и он проходит порог, система даст неверную выдержку. Именно поэтому проверяем top-1 relevance и supported-answer precision.'),
        ('Чем калибровка порога отличается от калибровки вероятностей?', 'Подбор порога задаёт эмпирическое правило принятия и отказа на данной выборке. Он не превращает BM25 score в вероятность. Вероятностная калибровка требует отдельной модели и метрик соответствия предсказанных вероятностей наблюдаемым частотам.'),
        ('Почему demo holdout нельзя считать экспертным benchmark?', 'Статьи и вопросы имеют общее автоматическое авторство, малый размер и похожую лексику. Отсутствие точных совпадений не устраняет такую зависимость. Нужна независимая экспертная разметка реальных обращений и проверка семантических групп.'),
        ('Что фиксирует SHA-256?', 'Хеш идентифицирует точные байты файла. Изменение статьи, пробела или порядка строк меняет хеш. Это полезно для воспроизводимости и отключения старого порога, но не доказывает истинность содержания и не заменяет подпись владельца.'),
        ('Как обновлять базу знаний?', 'Новая версия проходит аудит, получает новый fingerprint и требует повторной калибровки при изменении распределения score. Для надёжной эксплуатации индекс строится отдельно и переключается атомарно. Текущий API загружает индекс при старте и требует перезапуска.'),
        ('Что такое RAG?', 'Это процесс, в котором сначала извлекаются релевантные источники, затем ответ формируется с опорой на них. Retrieval и generation оцениваются отдельно: хороший генератор не исправит систематически плохую выдачу источников.'),
        ('Почему ответы сделаны цитатами?', 'Точная цитата позволяет программно проверить происхождение текста и избежать свободного добавления инструкций. Такой ответ менее гибок, чем LLM-перефразирование, но служит понятным baseline. Проверка цитаты подтверждает происхождение, а не правильность выбора статьи.'),
        ('Как проверяется LLM-провайдер?', 'Контрактные тесты подменяют HTTP-ответ и проверяют корректную цитату, выдуманный ID, выдуманный текст, пустой список и недоступность провайдера. Дополнительно локальная Qwen2.5 0.5B реально вызвана на четырёх выбранных calibration-кейсах. Это smoke интеграции; для вывода о качестве нужен независимый экспертный набор ответов.'),
        ('Что делать с prompt injection в статье?', 'Документы рассматриваются как недоверенные данные, а инструкции приложения задаются отдельно. В нашем ограниченном режиме LLM может выбрать только существующие цитаты, и сервер проверяет IDs и точные подстроки. Для свободной генерации и инструментов нужны дополнительные границы полномочий и предметная оценка.'),
        ('Когда нужны embeddings?', 'Когда релевантность часто выражается синонимами и смысловой близостью без общих слов. Dense retrieval может улучшить recall, но добавляет модель, хранение векторов, версионирование и свой профиль ошибок. Выбор делается по реальным запросам, а не по модности метода.'),
        ('Когда нужен reranker?', 'Когда первый этап возвращает нужные статьи, но ставит их слишком низко. Более дорогой cross-encoder можно применять только к небольшому списку кандидатов. Нужно измерять прирост MRR/top-1 и задержку полного запроса.'),
        ('Как устроен Transformer?', 'Self-attention позволяет токенам учитывать контекст других токенов, а позиционные признаки сохраняют информацию о порядке. Для классификации над представлением текста добавляют классификационную голову и обучают её с нужной функцией потерь. В этом проектном проходе такой эксперимент не выполнялся.'),
        ('Чем fine-tuning отличается от prompting?', 'Fine-tuning изменяет веса модели на обучающих данных. Prompting задаёт контекст и примеры в запросе без изменения весов. Оба подхода требуют независимой оценки, а стоимость inference и ограничения длины контекста могут различаться.'),
        ('Что дают LoRA и QLoRA?', 'LoRA обучает небольшие низкоранговые добавки к выбранным весам. QLoRA сочетает адаптеры с квантованной базовой моделью для экономии памяти. Это методы эффективного fine-tuning, а не автоматическая гарантия качества; нужны подходящая разметка и ресурсный бюджет.'),
        ('Чем liveness отличается от readiness?', 'Liveness подтверждает, что процесс отвечает. Readiness показывает, может ли он выполнять конкретную работу. В нашем API intent-модель и knowledge-индекс имеют разные readiness, поэтому отсутствие модели не обязано выключать поиск.'),
        ('Что измеряет HTTP P95?', 'Это значение, ниже которого лежит около 95 процентов измеренных задержек в данной серии запросов. Оно зависит от среды, прогрева, конкуренции и состава запросов. Малый последовательный benchmark не позволяет обещать P95 под промышленной нагрузкой.'),
        ('Почему контейнер не равен production готовности?', 'Контейнер фиксирует среду и способ запуска, но не добавляет автоматически TLS, резервирование, корректную работу нескольких workers или контроль качества. Мы проверили локальную сборку и healthcheck, а внешняя эксплуатационная приёмка остаётся отдельной задачей.'),
        ('Что рассказать о мониторинге и отказах?', 'Нужно наблюдать технические ошибки, latency, долю отказов, распределение intents, актуальность статей и качество по размеченной обратной связи. Наш /metrics содержит счётчики и суммарную длительность одного процесса. Он не измеряет качество сам по себе и не заменяет внешнюю систему мониторинга.')]
    for index, (question, answer) in enumerate(questions, 1):
        doc.add_heading(f'{index} {question.rstrip("?")}', level=2)
        doc.add_paragraph(answer)
    doc.add_heading('Источники новых технических решений', level=2)
    doc.add_paragraph('Ollama API и structured outputs: https://github.com/ollama/ollama/blob/main/docs/api.md. Использованы формат запроса /api/chat, stream=false и JSON schema для результата; конкретная модель не выбиралась и не измерялась.')
    doc.add_paragraph('Docker Compose healthcheck: https://docs.docker.com/reference/compose-file/services/. Конфигурация проекта проверена локальным запуском контейнера, статусом healthy и HTTP-запросами.')
    doc.add_paragraph('Карточка локальной модели: https://ollama.com/library/qwen2.5:0.5b. Использована Q4_K_M-версия размером около 398 MB; точный digest и размер записаны в артефакте проверки. Docker-запуск Ollama: https://docs.ollama.com/docker.')
